const routes = {
  'cards.list': '/voice/v1/cards.list',
  'cards.balance': '/voice/v1/cards.balance',
  'statement.week.get': '/voice/v1/statement.week.get',
  'statement.week.decide': '/voice/v1/statement.week.decide',
  'statement.week.change': '/voice/v1/statement.week.change',
  'contact.email.get': '/voice/v1/contact.email.get',
  'statement.pdf.send': '/voice/v1/statement.pdf.send',
};

const service = $json.params?.service;
const body = $json.body;
const supported = Object.prototype.hasOwnProperty.call(routes, service);
const hasData = body && typeof body === 'object' && body.data && typeof body.data === 'object';
const isValid = supported && hasData;

return {
  json: {
    service,
    isValid,
    targetUrl: isValid ? `https://freya-bank-statement-mock.genctrader48.workers.dev${routes[service]}` : '',
    body,
    errorBody: { error: 'invalid_request', message: supported ? 'Request must contain a data object.' : `Unsupported service: ${String(service ?? '')}` },
  },
};
